namespace RecipeShare.Models;

public class Category
{
    public string Slug { get; set; } = "";
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Category> _categories =
    [
        new() { Slug = "breakfast", Name = "Breakfast", Icon = "🥞", Description = "Start your day right" },
        new() { Slug = "lunch", Name = "Lunch", Icon = "🥗", Description = "Midday meals and salads" },
        new() { Slug = "dinner", Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes" },
        new() { Slug = "desserts", Name = "Desserts", Icon = "🍰", Description = "Sweet treats and bakes" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", CategorySlug = "breakfast",
            Ingredients = ["2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder"],
            Steps = ["Mix dry ingredients", "Whisk eggs and milk together", "Combine wet and dry", "Cook on griddle until golden"],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Caesar Salad", CategorySlug = "lunch",
            Ingredients = ["Romaine lettuce", "Croutons", "Parmesan cheese", "Caesar dressing", "Lemon juice"],
            Steps = ["Wash and chop lettuce", "Toss with dressing", "Add croutons and parmesan", "Squeeze lemon on top"],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Bolognese", CategorySlug = "dinner",
            Ingredients = ["400g spaghetti", "500g ground beef", "Onion", "Garlic", "Canned tomatoes", "Basil"],
            Steps = ["Cook spaghetti al dente", "Sauté onion and garlic", "Brown the beef", "Add tomatoes and simmer 20 min", "Serve over pasta"],
            AverageRating = 4.8, RatingCount = 25
        },
        new()
        {
            Id = 4, Title = "Chocolate Brownies", CategorySlug = "desserts",
            Ingredients = ["200g dark chocolate", "150g butter", "3 eggs", "200g sugar", "100g flour"],
            Steps = ["Melt chocolate and butter", "Whisk eggs and sugar", "Fold in chocolate mixture", "Add flour gently", "Bake at 180°C for 25 min"],
            AverageRating = 4.9, RatingCount = 30
        },
    ];

    private int _nextId = 5;

    public List<Category> GetCategories() => _categories;

    public Category? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public List<Recipe> GetRecipesByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

